use crate::{Result,api::{self,Api},json,reference,require,server::{self,Backend},service,upstream::Upstream};
use serde_json::json;
use std::path::Path;

pub fn run(output:&Path)->Result {
    reference::verify(output)?;let (baseline,root)=service::baseline(output)?;let mut port=0;
    for mode in ["none","http","http-fallback","generic-post","generic-get","ntfy","gotify","generic-rejected","unsupported","business"] {
        let mut paired=Vec::new();
        for (kind,backend) in [("node",Backend::Node(reference::node())),("rust",service::target()?)] {
            let label=format!("{kind}-notification-{mode}");let upstream=Upstream::new(port)?;let url=upstream.url();let parsed=reqwest::Url::parse(url)?;port=parsed.port().ok_or("Missing notification port")?;let authority=&url["http://".len()..];
            let configured=match mode {"none"=>String::new(),"http"=>format!("{url}/host/notification?title=[推送标题]&content=[推送内容]&repeat=[推送标题]"),"http-fallback"|"business"=>format!("{url}/host/notification?title=[推送标题]&content=[推送内容]"),"generic-post"=>format!("generic+{url}/host/notification?template=json&title=fixture-title"),"generic-get"=>format!("generic://{authority}/host/notification?disabletls=yes&method=GET&template=json&title=fixture-title"),"ntfy"=>format!("ntfy://{authority}/host/notification?scheme=http&title=fixture-title"),"gotify"=>format!("gotify://{authority}/host/notification/A12345678901234?disabletls=yes"),"generic-rejected"=>format!("generic+{url}/host/notification-error?template=json"),_=>"missing://fixture.invalid".into()};
            let mut document=baseline.clone();document["settings"]=json!({"logsMaxCount":100});for field in ["subs","collections","files","artifacts","tokens","archives"] {document[field]=json!([]);}let mut steps=Vec::new();
            if mode=="business" {
                let good=json!({"name":"good","source":"local","content":"ss://YWVzLTEyOC1nY206cGFzcw==@127.0.0.1:8388#fixture"});let mut same=good.clone();same["name"]=json!("same-good");let bad=json!({"name":"bad","source":"remote","url":format!("{url}/host/pipeline/failed")});let mut fallback=bad.clone();fallback["name"]=json!("fallback");fallback["ignoreFailedRemoteSub"]=json!("fallbackNotify");let mut duplicate=good.clone();duplicate["name"]=json!("duplicates-sub");duplicate["content"]=json!(format!("{}\n{}",good["content"].as_str().unwrap(),good["content"].as_str().unwrap()));let remote=json!({"name":"file-warning","source":"remote","url":bad["url"],"ignoreFailedRemoteFile":"enabled"});
                document["subs"]=json!([good,same,bad,fallback,duplicate]);document["collections"]=json!([{"name":"duplicates-col","subscriptions":["good","same-good"]}]);document["files"]=json!([remote]);let mut enabled=bad.clone();enabled["ignoreFailedRemoteSub"]=json!("enabled");
                for (path,body) in [("/api/preview/sub?target=JSON",enabled),("/api/preview/sub?target=JSON",fallback),("/api/preview/collection?target=JSON",json!({"name":"child-fallback","subscriptions":["good","fallback"]})),("/api/preview/collection?target=JSON",json!({"name":"collection-warning","subscriptions":["good","bad"],"ignoreFailedRemoteSub":"enabled"})),("/api/preview/collection?target=JSON",json!({"name":"collection-fallback","subscriptions":["bad"],"ignoreFailedRemoteSub":"fallbackNotify"})),("/api/preview/file",remote)] {steps.push(json!({"method":"POST","path":path,"body":body}));}
                for path in ["/api/file/file-warning","/download/duplicates-sub/JSON","/download/collection/duplicates-col?target=JSON"] {steps.push(json!({"path":path}));}
            }
            let mut root=root.clone();root["sub-store-logs"]=json!("[]");let (state,mut environment)=service::seed(output,&label,&document,&root)?;server::set(&mut environment,"SUB_STORE_PUSH_SERVICE",&configured);let api=Api::start(&backend,&environment,&state,output,&label)?;
            let expected=if steps.is_empty() {3} else {steps.len()};
            if steps.is_empty() {steps.push(json!({"method":"POST","path":"/api/preview/sub?target=JSON","body":{"name":"notification-check","source":"local","content":"ss://YWVzLTEyOC1nY206cGFzcw==@127.0.0.1:8388#fixture","process":[{"type":"Script Operator","args":{"arguments":{"title":if mode=="http-fallback" {""} else {"通知🙂"}},"content":"function operator(proxies){if(!$substore.env.isNode&&(typeof process!=='undefined'||typeof require!=='undefined'))throw new Error('Node runtime leaked');for(let index=0;index<3;index++)$substore.notify($arguments.title?$arguments.title+index:'','子标题'+index,'正文🙂',{'open-url':'https://example.invalid/open','media-url':'https://example.invalid/media'});return proxies;}"}}]}}));}
            for step in steps {let response=api.response(&step)?;require(response["status"]==200,"Notification trigger failed")?;}
            let mut completed=Vec::new();if !configured.is_empty() {api::wait(||{completed=api.data(&json!({"path":"/api/logs?keyword=%5BPush%20Service%5D"}))?["logs"].as_array().ok_or("Missing push service logs")?.clone();Ok(completed.len()==expected)})?;}
            let mut messages=completed.iter().map(|entry|Ok(entry["message"].as_str().ok_or("Missing notification result log")?.to_owned())).collect::<Result<Vec<_>>>()?;
            if ["generic-rejected","unsupported"].contains(&mode) {require(messages.iter().all(|message|message.contains("ERROR:")),"Rejected notification did not log error")?;} else if !configured.is_empty() {require(messages.iter().all(|message|message.contains("RES:")),"Successful notification did not log response")?;}
            let notices=api.data(&json!({"path":"/api/logs?keyword=%5BNotify%5D"}))?["logs"].as_array().ok_or("Missing notification logs")?.clone();require(notices.len()==expected,"Missing or extra notifications")?;
            if mode=="business" {for fragment in ["预览订阅失败","预览组合订阅失败","预览文件失败","处理文件失败","🤔 原因：","⚠️ 订阅 duplicates-sub","⚠️ 组合订阅 duplicates-col","多媒体: https://cdn3.iconfinder.com"] {require(notices.iter().any(|entry|entry["message"].as_str().is_some_and(|message|message.contains(fragment))),format!("Business notice missing {fragment}"))?;}}
            else {require(notices.iter().all(|entry|entry["message"].as_str().is_some_and(|message|message.contains("正文🙂\n点击跳转: https://example.invalid/open\n多媒体: https://example.invalid/media"))),"Notification body/options changed")?;}
            let mut requests=upstream.fixture.snapshot().iter().filter(|entry|mode!="business"||entry["path"].as_str().is_some_and(|path|path.starts_with("/host/notification?"))).map(|entry|{let headers=entry["headers"].as_object().ok_or("Missing provider headers")?.iter().filter(|(key,_)|["content-type","authorization","title","priority"].contains(&key.as_str())).map(|(key,value)|(key.clone(),value.clone())).collect::<serde_json::Map<_,_>>();Ok(json!({"method":entry["method"],"path":entry["path"],"body":entry["body"],"headers":headers}))}).collect::<Result<Vec<_>>>()?;
            require(requests.len()==if ["none","unsupported"].contains(&mode) {0} else {expected},"Notification provider request count changed")?;if mode=="generic-get" {require(requests.iter().all(|entry|entry["method"]=="GET"&&entry["body"].as_str().is_some_and(|body|body.contains("正文🙂"))),"Generic GET did not retain request body")?;}
            requests.sort_by_key(json::stringify);messages.sort();let mut notices=notices.iter().map(|entry|entry["message"].as_str().ok_or("Missing notice message").map(String::from)).collect::<std::result::Result<Vec<_>,_>>()?;notices.sort();let proof=json!({"requests":requests,"messages":messages,"notices":notices});json::write_new(output.join(format!("{label}.json")),&proof)?;paired.push(proof);api.send(&json!({"path":"/api/settings"}),200)?;upstream.fixture.healthy()?;
        }
        json::check(&paired[0],&paired[1],false)?;
    }Ok(())
}
